package es.jllopez.neis.infrastructure.adapter.system;

import es.jllopez.neis.domain.model.SystemInfo;
import es.jllopez.neis.domain.port.RuntimeInfoPort;
import org.springframework.boot.info.BuildProperties;
import org.springframework.stereotype.Component;

/**
 * Connector (driven adapter) that reads runtime information from the
 * Spring Boot build properties generated by the Maven build-info goal.
 */
@Component
public class MavenRuntimeInfoConnector implements RuntimeInfoPort {

    private final BuildProperties buildProperties;

    public MavenRuntimeInfoConnector(BuildProperties buildProperties) {
        this.buildProperties = buildProperties;
    }

    @Override
    public SystemInfo loadSystemInfo() {
        return new SystemInfo(
                buildProperties.getName(),
                buildProperties.get("description") != null
                        ? buildProperties.get("description")
                        : "News and Events Information System",
                buildProperties.getVersion(),
                System.getProperty("java.version"));
    }
}
